#!/usr/bin/env bash
# projects/{{JOB}}/finalize.sh — promote the newest render to
# outputs/{{JOB}}.final.mp4 and copy it to ~/Downloads.
#
# Generated by scripts/new-project.sh from lib/templates/finalize.sh.
# Safe to re-run. Does not touch raw/ or delete anything.
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo="$(cd "$here/../.." && pwd)"
. "$repo/lib/common.sh"

job="{{JOB}}"
outputs="$here/outputs"

# "Newest render" = the most recently modified mp4/mov in outputs/ that
# isn't already the .final file and isn't a dotfile cache artifact
# (.roughcut.mp4, .transcript.json, etc).
newest="$(
  find "$outputs" -maxdepth 1 -type f \( -iname '*.mp4' -o -iname '*.mov' \) ! -name '.*' ! -name "${job}.final.mp4" \
    -exec ls -t {} + 2>/dev/null | head -n1
)"

[ -n "${newest:-}" ] || hf_die "no renders found in $outputs to finalize"

final="$outputs/${job}.final.mp4"
if [ "$newest" != "$final" ]; then
  cp "$newest" "$final"
fi

downloads="$HOME/Downloads"
mkdir -p "$downloads"
cp "$final" "$downloads/${job}.final.mp4"

hf_log "promoted: $newest"
hf_log "        -> $final"
hf_log "        -> $downloads/${job}.final.mp4"
